152: function generateHint(word,category){
153:  const rules=HINT_RULES[category];if(!rules)return '';
154:  const key=word.toLowerCase();
155:  const group=rules.groups.find(rule=>rule.words.split('|').includes(key));
156:  const choices=group?group.hints:rules.fallback;
157:  const index=[...key].reduce((sum,char)=>sum+char.charCodeAt(0),0)%choices.length;
158:  const hint=choices[index];
159:  const hintWords=hint.toLowerCase().split(/[^a-z0-9]+/).filter(Boolean),secretWords=key.split(/[^a-z0-9]+/).filter(Boolean);
160:  const revealsWord=secretWords.length&&hintWords.some((_,i)=>secretWords.every((part,j)=>hintWords[i+j]===part));
161:  return revealsWord?rules.fallback[(index+1)%rules.fallback.length]:hint;
162: }
