Index: styles.css
===================================================================
--- styles.css
+++ styles.css
@@ -478,10 +478,17 @@
 .pack-modal{background:rgba(24,38,29,.56);backdrop-filter:blur(5px);padding:max(20px,env(safe-area-inset-top)) max(20px,env(safe-area-inset-right)) max(20px,env(safe-area-inset-bottom)) max(20px,env(safe-area-inset-left))}
 .modal-card{max-height:min(90svh,720px);overflow:auto;box-shadow:0 24px 80px rgba(17,35,23,.22)}
 .toast{bottom:max(25px,calc(env(safe-area-inset-bottom) + 12px));max-width:calc(100vw - 32px);text-align:center}
 .player-list{max-height:min(55vh,520px);align-content:start;overscroll-behavior:contain;scrollbar-gutter:stable}
-.imposter-choices{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-height:min(34vh,220px);overflow-y:auto;align-content:start;overscroll-behavior:contain;scrollbar-gutter:stable}
-.imposter-choices button{min-width:0;padding:8px 5px}
+.imposter-stepper{display:flex;align-items:center;gap:8px;width:max-content;max-width:100%;margin-top:11px}
+.imposter-stepper button{display:grid;place-items:center;width:48px;height:48px;padding:0;border:1px solid #214730;border-radius:11px;background:#214730;color:#f8faef;font:600 23px/1 'Space Grotesk',sans-serif;transition:background .18s,border-color .18s,transform .18s,box-shadow .18s}
+.imposter-stepper button:hover:not(:disabled){background:#2b563a;border-color:#2b563a;box-shadow:0 4px 10px rgba(31,71,47,.15);transform:translateY(-1px)}
+.imposter-stepper button:active:not(:disabled){transform:translateY(0)}
+.imposter-stepper .imposter-count{display:grid;place-items:center;min-width:56px;height:48px;border:1px solid #e0e5db;border-radius:11px;background:#fffefa;color:#20392a;font:600 20px/1 'Space Grotesk',sans-serif}
+.imposter-stepper button:disabled{background:#e8ede2;border-color:#dfe5dc;color:#9aa398;opacity:1}
+.imposter-stepper button:focus-visible{outline-offset:3px}
+.recommendation{display:block;margin-top:8px}
+.recommendation:disabled{cursor:not-allowed;opacity:.55}
 @media(max-width:650px){.player-list{max-height:min(50vh,420px)}}
 @media(max-width:650px){
  html{scrollbar-gutter:auto}body{background-attachment:scroll}.app-shell{padding-right:max(14px,env(safe-area-inset-right));padding-left:max(14px,env(safe-area-inset-left))}
  .topbar{gap:10px}.top-meta{min-width:0;letter-spacing:.65px}.icon-button{flex:none}.party-bar,.panel,.phase-card,.stats-panel,.clue-card{box-shadow:0 12px 30px rgba(28,48,34,.055),0 1px 4px rgba(28,48,34,.025)}

